 3	export type AsyncResult<T> = {status: 'applied'; data: T} | {status: 'error'; error: unknown} | {status: 'superseded'};
 4	export type AsyncState<T> = {data: T; status: 'idle' | 'pending' | 'ready' | 'error'; error: unknown};
 5	
 6	// One resource, one latest-started operation. Cancellation is advisory: generation
 7	// checks also reject results from adapters which ignore AbortSignal.
 8	export function useAsyncResource<T>(initialData: T) {
 9	  const [state, setState] = useState<AsyncState<T>>({data: initialData, status: 'idle', error: null});
10	  const lifetime = useRef({active: true, generation: 0, controller: null as AbortController | null});
11	  const invalidate = useCallback(() => {
12	    const current = lifetime.current;
13	    const generation = ++current.generation, controller = current.controller;
14	    // Abort dispatches user listeners synchronously. Detach the old controller
15	    // first, and keep our reserved generation if a listener starts newer work.
16	    current.controller = null;
17	    controller?.abort();
18	    return generation;
19	  }, []);
20	  useEffect(() => {
21	    lifetime.current.active = true;
22	    return () => {lifetime.current.active = false; invalidate();};
23	  }, [invalidate]);
24	  const run = useCallback(async (operation: (signal: AbortSignal) => Promise<T>, beforeApply?: (data:T)=>void): Promise<AsyncResult<T>> => {
25	    if (!lifetime.current.active) return {status: 'superseded'};
26	    const generation = invalidate();
27	    const current = () => lifetime.current.active && lifetime.current.generation === generation;
28	    if (!current()) return {status: 'superseded'};
29	    const controller = new AbortController();
30	    lifetime.current.controller = controller;
31	    setState(previous => ({...previous, status: 'pending', error: null}));
32	    try {
33	      const data = await operation(controller.signal);
34	      if (!current()) return {status: 'superseded'};
35	      beforeApply?.(data);
36	      if (!current()) return {status: 'superseded'};
37	      setState({data, status: 'ready', error: null});
38	      return {status: 'applied', data};
39	    } catch (error) {
40	      if (!current()) return {status: 'superseded'};
41	      setState(previous => ({...previous, status: 'error', error}));
42	      return {status: 'error', error};
43	    } finally {
44	      if (current()) lifetime.current.controller = null;
45	    }
46	  }, [invalidate]);
47	  const publish = useCallback((data: T, beforeApply?: (data:T)=>void) => {
48	    if (!lifetime.current.active) return;
49	    const generation = invalidate();
50	    if (!lifetime.current.active || lifetime.current.generation !== generation) return;
51	    beforeApply?.(data);
52	    if (!lifetime.current.active || lifetime.current.generation !== generation) return;
53	    setState({data, status: 'ready', error: null});
54	  }, [invalidate]);
55	  return {...state, run, publish};
56	}
