 4	export type PageData = {scope: string; resources: Record<string, unknown>};
 5	export type RouteSnapshot<T> = {data: T | undefined; hasData: boolean;
 6	  status: 'idle' | 'pending' | 'ready' | 'error'; error: unknown};
 7	const empty: RouteSnapshot<unknown> = Object.freeze({data:undefined,hasData:false,status:'idle',error:null});
 8	type Entry = {state: RouteSnapshot<unknown>; controller?: AbortController};
 9	
10	// Memory only: no cross-document/user storage. Writes supersede pending reads.
11	export function createRouteDataStore(initial: PageData = {scope:'public',resources:{}}) {
12	  let entries=new Map<string,Entry>(), scope=initial.scope;
13	  const listeners=new Set<()=>void>();
14	  const notify=()=>listeners.forEach(listener=>listener());
15	  const ready=(data:unknown):Entry=>({state:{data,hasData:true,status:'ready',error:null}});
16	  for (const [key,value] of Object.entries(initial.resources)) entries.set(key,ready(value));
17	  const replace=(key:string,entry?:Entry)=>{
18	    const old=entries.get(key);
19	    if(entry) entries.set(key,entry); else entries.delete(key);
20	    old?.controller?.abort();notify();
21	  };
22	  return {
23	    get scope(){return scope;},
24	    read<T>(key:string):RouteSnapshot<T>{return (entries.get(key)?.state ?? empty) as RouteSnapshot<T>;},
25	    subscribe(listener:()=>void){listeners.add(listener);return ()=>{listeners.delete(listener)};},
26	    publish<T>(key:string,data:T){replace(key,ready(data));},
27	    invalidate(key:string){replace(key);},
28	    reset(next:PageData){
29	      const previous=entries;
30	      entries=new Map(Object.entries(next.resources).map(([key,value])=>[key,ready(value)]));
31	      scope=next.scope;
32	      previous.forEach(entry=>entry.controller?.abort());notify();
33	    },
34	    async load<T>(key:string,operation:(signal:AbortSignal)=>Promise<T>):Promise<AsyncResult<T>> {
35	      const previous=entries.get(key)?.state ?? empty, controller=new AbortController();
36	      const entry:Entry={state:{...previous,status:'pending',error:null},controller};
37	      replace(key,entry);
38	      const current=()=>entries.get(key)===entry;
39	      if(!current())return {status:'superseded'};
40	      try {
41	        const data=await operation(controller.signal);
42	        if(!current())return {status:'superseded'};
43	        entry.state=ready(data).state;entry.controller=undefined;notify();
44	        return current() ? {status:'applied',data} : {status:'superseded'};
45	      } catch(error) {
46	        if(!current())return {status:'superseded'};
47	        entry.state={...previous,status:'error',error};entry.controller=undefined;notify();
48	        return current() ? {status:'error',error} : {status:'superseded'};
49	      }
50	    },
51	  };
52	}
