54	export function readInitialPageData():PageData | undefined {
55	  if(typeof document==='undefined')return;
56	  const text=document.getElementById('page-data')?.textContent;
57	  if(!text)return;
58	  const data=JSON.parse(text);
59	  if(data.version!==1 || data.location!==location.pathname+location.search ||
60	    typeof data.scope!=='string' || !data.scope || !data.resources ||
61	    typeof data.resources!=='object' || Array.isArray(data.resources)) {
62	    throw new Error('Invalid page data for the current document');
63	  }
64	  return data;
65	}
