72	// Prefer the document snapshot; fetch a missing resource once across consumers.
73	// Errors need explicit retry (invalidate/load), never an automatic request loop.
74	export function usePageResource<T>(key:string,read:(signal:AbortSignal)=>Promise<T>,store=routeData):RouteSnapshot<T> {
75	  const snapshot=useRouteData<T>(key,store);
76	  useEffect(()=>{
77	    if(store.read(key).status==='idle')void store.load(key,read);
78	    // Shared reads survive one subscriber unmounting. reset/invalidate owns
79	    // cancellation. useSession resets the default store on successful changes;
80	    // custom session flows must reset their own user/permission scope.
81	  },[key,read,store,snapshot.status]);
82	  return snapshot;
83	}
